"""Items wave 2, batch 8 (63 sprites)."""
from items2 import place
from items_keys import BATCH_KEYS

KEYS = BATCH_KEYS[8]


def _s(*rows, **kw):
    return place(list(rows), **kw)



def _sign(*mid):
    """Terracotta sign board on two legs; mid = emblem rows (8 chars)."""
    rows = ["nnnnnnnnnnnn", "n2222222222n"] + ["n2" + m + "2n" for m in mid]
    rows += ["n2222222222n", "nnnnnnnnnnnn", "...n....n...", "...N....N..."]
    return _s(*rows)


